import {readSkin} from './skin-format.js';
const form=document.querySelector('form'),query=document.getElementById('query'),list=document.getElementById('destinations'),status=document.getElementById('status');
const baseProviders=[['Internet Archive metadata','https://archive.org/advancedsearch.php','q','internet-archive'],['Open Library books','https://openlibrary.org/search','q','open-library'],['Library of Congress','https://www.loc.gov/search/','q','library-of-congress']];
function preferredProviders(){try{if(localStorage.getItem('reckoner-appearance-v1')!=='community')return baseProviders;const skin=readSkin(localStorage.getItem('reckoner-community-skin-v1'));return [...skin.repositories.map(id=>baseProviders.find(p=>p[3]===id)),...baseProviders.filter(p=>!skin.repositories.includes(p[3]))];}catch{return baseProviders;}}
let attempts=[];
function links(){list.replaceChildren();status.textContent='';const q=query.value.trim();if(!q)return;if(q.length>1000){status.textContent='Keep the query below 1,000 characters.';return;}
 for(const [name,base,key] of preferredProviders()){const u=new URL(base);u.searchParams.set(key,q);const row=document.createElement('li'),a=document.createElement('a'),preview=document.createElement('small');a.textContent=name;a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';preview.textContent=u.href;preview.style.display='block';preview.style.overflowWrap='anywhere';a.addEventListener('click',()=>{if(attempts.length>=300){status.textContent='Search history is full. Save it, then reopen this search panel for a new session. This request will not be recorded.';return;}attempts.push({destination:name,url:u.href,query:q,openedAt:new Date().toISOString(),status:'opening_requested_result_not_checked'});status.textContent='Requested '+name+'. Check the results there; no opening success or result count has been verified.';});row.append(a,preview);list.append(row);}}
form.addEventListener('submit',e=>{e.preventDefault();links();});query.addEventListener('input',links);
document.getElementById('export-search').addEventListener('click',()=>{const body={schema:'reckoner.search_attempts.v0.1',queryDraft:query.value,attempts,scope:'Manual link openings, not verified search results. No source rights or archive absence inferred.'};const url=URL.createObjectURL(new Blob([JSON.stringify(body,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='search-attempts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

try{const prior=localStorage.getItem('reckoner-last-review-url-v1');if(prior){const u=new URL(prior);if(u.origin===location.origin&&u.pathname.endsWith('/index.html'))document.getElementById('return-review').href=u.href;}}catch{}
